BEGIN READ ONLY;
SET LOCAL statement_timeout='30s';
SET LOCAL lock_timeout='2s';
SELECT json_build_object('check','database','at',clock_timestamp(),'database_bytes',pg_database_size(current_database()),'version',version(),'checksums',current_setting('data_checksums'),'invalid_indexes',(SELECT count(*) FROM pg_index WHERE NOT indisvalid OR NOT indisready),'unvalidated_constraints',(SELECT count(*) FROM pg_constraint WHERE NOT convalidated));
SELECT json_build_object('check','stats','value',row_to_json(x)) FROM (SELECT numbackends,xact_commit,xact_rollback,deadlocks,temp_files,temp_bytes,blk_read_time,blk_write_time,stats_reset FROM pg_stat_database WHERE datname=current_database()) x;
SELECT json_build_object('check','relations','rows',json_agg(x)) FROM (SELECT relname,pg_total_relation_size(relid) total_bytes,n_live_tup,n_dead_tup,last_vacuum,last_autovacuum,last_analyze,last_autoanalyze FROM pg_stat_user_tables ORDER BY pg_total_relation_size(relid) DESC LIMIT 20) x;
SELECT json_build_object('check','queries','rows',json_agg(x)) FROM (SELECT application_name,state,wait_event_type,wait_event,count(*),max(clock_timestamp()-xact_start) oldest_transaction FROM pg_stat_activity WHERE datname='proof_indexer' GROUP BY 1,2,3,4) x;
SELECT json_build_object('check','tablespaces','rows',json_agg(x)) FROM (SELECT spcname,pg_tablespace_location(oid) path,pg_tablespace_size(oid) bytes FROM pg_tablespace) x;
SELECT json_build_object('check','extensions','rows',json_agg(x)) FROM (SELECT extname,extversion FROM pg_extension) x;
SELECT json_build_object('check','worker_metadata','rows',json_agg(x)) FROM (SELECT * FROM proof_indexer.meta WHERE key ILIKE '%worker%' OR key ILIKE '%pending%' OR key ILIKE '%blockScan%' LIMIT 15) x;
ROLLBACK;

